mapper.select:
SELECT 
  FROM com50_item
 WHERE 1=1
   AND com50_item_type = #{itemType}
   AND CONCAT(com50_item_cd, com50_item_nm) ILIKE #{searchText}
 ORDER BY com50_item_cd
 LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
  FROM com50_item
 WHERE 1=1
   AND com50_item_type = #{itemType}
   AND CONCAT(com50_item_cd, com50_item_nm) ILIKE #{searchText}

SELECT COUNT(*)
  FROM com50_item
 WHERE com50_item_cd  = #{itemCode}
   AND com50_item_id != #{itemId}

mapper.update:
UPDATE com50_item
   SET com50_item_cd = #{req.itemCode},
       com50_item_nm = #{req.itemName}
 WHERE com50_item_id = #{req.itemId}

mapper.delete:
DELETE FROM com50_item
 WHERE com50_item_id IN
#{id}
